Review these previously model-flagged conflict pairs against the supplied quotations and scope/date fields. Do not assume every pair is a conflict. Different products, origins, tariff programs, or dated stages are not automatically contradictory. Only use apparent_same_scope_conflict when the supplied claims appear incompatible on the same scope/date; otherwise distinguish dated progression, differing scope, complementary claims, and missing scope. Do not verify current law from memory. Explain the reason briefly for every pair.
UNTRUSTED_EVIDENCE_JSON:
{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_9b3d8bafd4b4589696a468db", "claim_ids": ["claim_1814f1486ad1db5ee5a4fb75", "claim_4dfcf864b7bd49a740be88ae"], "query_ids": ["q_179"], "claims": [{"claim_id": "claim_1814f1486ad1db5ee5a4fb75", "quote": "Distributed Processing Technology assembles all the components onto the foreign raw printed circuit board in the United States, and thus the same rationale applies. The board would be substantially transformed.", "url": "https://rulings.cbp.gov/ruling/735306", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"company": "Distributed Processing Technology"}}, {"claim_id": "claim_4dfcf864b7bd49a740be88ae", "quote": "the PCBA does not undergo a change in name, character, and use during the final assembly process occurring in China, which is comparatively simple in nature.", "url": "https://www.regulations.gov/document/USCBP-2024-0016-0001", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_e60e68bdbfa7599973b821c2", "claim_ids": ["claim_30ff734629c86cf97ece229a", "claim_5d8dfce2aaa61030f4c7a55f"], "query_ids": ["q_181"], "claims": [{"claim_id": "claim_30ff734629c86cf97ece229a", "quote": "In 2025, President Donald Trump imposed 25% tariffs on U.S. imports of automobiles and certain automobile parts under Section 232.", "url": "https://www.congress.gov/crs-product/IN12545", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "President Donald Trump", "tariff_program": "Section 232", "affected_product": "U.S. imports of automobiles and certain automobile parts", "duty_rate": "25%", "effective_date": "2025"}}, {"claim_id": "claim_5d8dfce2aaa61030f4c7a55f", "quote": "Those duties, which are now 15% on cars built in Europe, South Korea, and Japan, remain in force.", "url": "https://www.kbb.com/tariffs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 of the Trade Expansion Act of 1962", "affected_product": "cars", "duty_rate": "15%", "reported_policy_status": "remain in force"}}]}, {"pair_id": "conflict_3ea8a5f4da0f5b37dee7498f", "claim_ids": ["claim_30ff734629c86cf97ece229a", "claim_741a5f0bc51887e0963b841d"], "query_ids": ["q_181"], "claims": [{"claim_id": "claim_30ff734629c86cf97ece229a", "quote": "In 2025, President Donald Trump imposed 25% tariffs on U.S. imports of automobiles and certain automobile parts under Section 232.", "url": "https://www.congress.gov/crs-product/IN12545", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "President Donald Trump", "tariff_program": "Section 232", "affected_product": "U.S. imports of automobiles and certain automobile parts", "duty_rate": "25%", "effective_date": "2025"}}, {"claim_id": "claim_741a5f0bc51887e0963b841d", "quote": "auto imports from the EU, Japan, and South Korea face a 15% total", "url": "https://www.congress.gov/crs-product/IN12545", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "United States", "affected_product": "auto imports", "exporting_country": "EU, Japan, and South Korea", "duty_rate": "15%"}}]}, {"pair_id": "conflict_035cd4ff4930cadb8a6e79e7", "claim_ids": ["claim_5d8dfce2aaa61030f4c7a55f", "claim_b2a4e3acb2a0cc3fca8542db"], "query_ids": ["q_181"], "claims": [{"claim_id": "claim_5d8dfce2aaa61030f4c7a55f", "quote": "Those duties, which are now 15% on cars built in Europe, South Korea, and Japan, remain in force.", "url": "https://www.kbb.com/tariffs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 of the Trade Expansion Act of 1962", "affected_product": "cars", "duty_rate": "15%", "reported_policy_status": "remain in force"}}, {"claim_id": "claim_b2a4e3acb2a0cc3fca8542db", "quote": "President Trump has announced a 25% tariff on all cars built outside the United States and on many parts used in cars built here.", "url": "https://www.kbb.com/tariffs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "cars", "duty_rate": "25%"}}]}, {"pair_id": "conflict_12acddc47fb77d1d36a468b7", "claim_ids": ["claim_741a5f0bc51887e0963b841d", "claim_b2a4e3acb2a0cc3fca8542db"], "query_ids": ["q_181"], "claims": [{"claim_id": "claim_741a5f0bc51887e0963b841d", "quote": "auto imports from the EU, Japan, and South Korea face a 15% total", "url": "https://www.congress.gov/crs-product/IN12545", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "United States", "affected_product": "auto imports", "exporting_country": "EU, Japan, and South Korea", "duty_rate": "15%"}}, {"claim_id": "claim_b2a4e3acb2a0cc3fca8542db", "quote": "President Trump has announced a 25% tariff on all cars built outside the United States and on many parts used in cars built here.", "url": "https://www.kbb.com/tariffs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "cars", "duty_rate": "25%"}}]}, {"pair_id": "conflict_31512eb7092ca0d71a8995da", "claim_ids": ["claim_4a1b64e798f18b7e3c03ca1c", "claim_a06f25609e7d6892f8808dfd"], "query_ids": ["q_183"], "claims": [{"claim_id": "claim_4a1b64e798f18b7e3c03ca1c", "quote": "Automotive display modules without systems-on-chips (SoCs) are classified as standalone components under HTSUS 8528.59.25xx", "url": "https://omdia.tech.informa.com/om135783/display-dynamics--may-2025-us-automotive-tariff-analysis-and-its-impact-on-automotive-displays", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Automotive display modules without systems-on-chips (SoCs)", "hts_code": "HTSUS 8528.59.25xx"}}, {"claim_id": "claim_a06f25609e7d6892f8808dfd", "quote": "14-inch flexible LCD-based display module using OLED backlight technology, no drivers included. Still classifies under HTS 8524.11.90.00 as liquid crystal 'other' module despite hybrid tech.", "url": "https://tariffs.wove.com/us/tariff/8524.11.90.00/14-inch-flexible-oled-lcd-hybrid-module", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8524.11.90.00"}}]}, {"pair_id": "conflict_a57780565482b2b948a1372f", "claim_ids": ["claim_c9b0d26f6115207615d607f3", "claim_f504c73b33d4e08c19fb865d"], "query_ids": ["q_188"], "claims": [{"claim_id": "claim_c9b0d26f6115207615d607f3", "quote": "By application of GRI 1, AUSR 1(a), and GRI 6, the HUD is classified in heading 8531, HTSUS, specifically in subheading 8531.80.90, which", "url": "https://www.tarifflens.ai/rulings/H304224", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "HUD", "hts_code": "8531.80.90"}}, {"claim_id": "claim_f504c73b33d4e08c19fb865d", "quote": "Head Up Display worth $145,196 under HS Code 85269190 have been imported", "url": "https://www.zauba.com/import-head+up+display/hs-code-85269190-hs-code.html", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "85269190", "exporting_country": "Taiwan"}}]}, {"pair_id": "conflict_ab140e20a5db0fec29df840c", "claim_ids": ["claim_75699b58d4a4a2ba52a18d45", "claim_c285a022a64271a2eab3d11a"], "query_ids": ["q_19", "q_307", "q_5"], "claims": [{"claim_id": "claim_75699b58d4a4a2ba52a18d45", "quote": "Natural graphite will face tariffs of 25%, as will permanent magnets, starting 2026.", "url": "https://mobilitynotes.com/summary-of-ev-related-u-s-tariffs-on-chinese-imports", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "permanent magnets", "duty_rate": "25%", "effective_date": "2026"}}, {"claim_id": "claim_c285a022a64271a2eab3d11a", "quote": "Natural graphite will face tariffs of 25%, as will permanent magnets, starting 2026.", "url": "https://mobilitynotes.com/summary-of-ev-related-u-s-tariffs-on-chinese-imports", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Natural graphite", "duty_rate": "25%", "effective_date": "2026"}}]}, {"pair_id": "conflict_154a5c554faf8f3955e50ac0", "claim_ids": ["claim_12b283d65114c014e5f15732", "claim_6edeba07cb0873e118bb5b78"], "query_ids": ["q_192"], "claims": [{"claim_id": "claim_12b283d65114c014e5f15732", "quote": "In HQ H026661, dated July 8, 2008, CBP classified an LCD display for auto/marine/industrial applications in heading 8531, HTSUS.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H325872&highlight=category%3AClassification", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "CBP", "tariff_program": "HTSUS", "affected_product": "LCD display for auto/marine/industrial applications"}}, {"claim_id": "claim_6edeba07cb0873e118bb5b78", "quote": "the subject LCD display module is classified in heading 8528, specifically subheading 8528.59.25, HTSUS", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H325872&highlight=category%3AClassification", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Gregory Connor, Chief Electronics, Machinery, Automotive, and International Nomenclature Branch", "tariff_program": "HTSUS", "affected_product": "LCD display module", "hts_code": "8528.59.25", "duty_rate": "free"}}]}, {"pair_id": "conflict_5c7693230239d1e702e5867f", "claim_ids": ["claim_6edeba07cb0873e118bb5b78", "claim_76ddf850e9a24897e7cfb519"], "query_ids": ["q_192"], "claims": [{"claim_id": "claim_6edeba07cb0873e118bb5b78", "quote": "the subject LCD display module is classified in heading 8528, specifically subheading 8528.59.25, HTSUS", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H325872&highlight=category%3AClassification", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Gregory Connor, Chief Electronics, Machinery, Automotive, and International Nomenclature Branch", "tariff_program": "HTSUS", "affected_product": "LCD display module", "hts_code": "8528.59.25", "duty_rate": "free"}}, {"claim_id": "claim_76ddf850e9a24897e7cfb519", "quote": "In HQ H049555, dated April 13, 2009, CBP classified automotive LCD modules used as radio/message displays (to display time, velocity in miles per hour, climate control, compass, music controls, and Bluetooth connection status) in heading 8531, HTSUS.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H325872&highlight=category%3AClassification", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "CBP", "tariff_program": "HTSUS", "affected_product": "automotive LCD modules used as radio/message displays"}}]}]}
